import { useState, useTransition, useDeferredValue, memo } from "react";

const ITEMS = Array.from({ length: 2000 }, (_, i) => "Mục " + i);

// Danh sách đắt: chỉ render lại khi `query` (đã trì hoãn) đổi
const List = memo(function List({ query }) {
  const shown = ITEMS.filter((x) => x.includes(query)).slice(0, 50);
  return <ul>{shown.map((x) => <li key={x}>{x}</li>)}</ul>;
});

export default function App() {
  const [text, setText] = useState("");
  const deferred = useDeferredValue(text);      // phiên bản "chậm hơn" của text
  const [isPending, startTransition] = useTransition();
  const [tab, setTab] = useState("a");

  return (
    <div>
      <input id="q" value={text} onChange={(e) => setText(e.target.value)} />   {/* cập nhật KHẨN CẤP: ô nhập luôn mượt */}
      <List query={deferred} />                                                {/* cập nhật HOÃN được */}
      <button id="tab" onClick={() => startTransition(() => setTab(tab === "a" ? "b" : "a"))}>Tab {tab}</button>
      {isPending && <span id="pending">…</span>}
    </div>
  );
}

